    let mean_ratio = (mean / capacity).clamp(0.0, 1.0);
    let progress_curve = progress * progress;

    let lookahead = next_item_size as f64;
    let lookahead_penalty = if lookahead > 0.0 {
        let uncovered = (lookahead - post_residual as f64).max(0.0);
        uncovered * uncovered / capacity
    } else {
        0.0
    };

    let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    let clustering = (open - 1.0) / open;
    let fragmentation = post_ratio * post_ratio * (1.0 - mean_ratio);

