    let mean_gap = (mean - post).clamp(-capacity, capacity);

    let progress_centered = progress - 0.5;
    let progress_sq = progress * progress;
    let progress_cube = progress_sq * progress;

    let mut score = post;
    score += 0.65 * progress_centered * post;
    score += 0.25 * progress_sq * post;
    score -= 0.20 * progress_cube * post;

    score += 18.0 * waste_ratio * (1.0 - progress);
    score -= 11.0 * utilization * progress;
    score += 8.0 * fill_ratio * mean_gap;
    score -= 4.0 * fill_ratio * (mean - residual);

