        let lookahead_fit = (next <= post) as u8 as f64;
        let scarcity = (next / capacity).clamp(0.0, 1.0);
        score += 13.0 * scarcity * (1.0 - lookahead_fit);
        score -= 7.0 * (1.0 - scarcity) * lookahead_fit * progress;
    }

    if fitting_bins_count <= 1 {
        score -= 9.0 * progress * fill_ratio;
    }

    if bin_residual == bin_capacity {
        score += 7.0;
        score += 5.0 * (1.0 - progress);
    }

    score -= 0.015 * open_bins_count as f64 * fill_ratio * (1.0 - progress);

    score
}

