pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let residual = post_residual as f64;
    let capacity = bin_capacity as f64;
    let item = item_size as f64;
    let mean = mean_residual;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;

    let normalized_residual = (residual / capacity).clamp(0.0, 1.0);
    let normalized_mean = (mean / capacity).clamp(0.0, 1.0);
    let normalized_item = (item / capacity).clamp(0.0, 1.0);
