    let progress = progress.clamp(0.0, 1.0);

    let mut score = residual;
    score += 18.0 * normalized_residual * normalized_residual;
    score -= 22.0 * normalized_residual * progress * (1.0 - progress);
    score += 13.0 * normalized_residual * normalized_mean;
    score -= 9.0 * normalized_residual * normalized_next;
    score -= 7.0 * normalized_item * progress;
    score += 11.0 * normalized_mean * (1.0 - progress);
    score += 5.0 * open * (1.0 - normalized_residual);
    score -= 8.0 * (fitting / open.max(1.0));
    score -= 15.0 * (1.0 - fitting / open.max(1.0)) * progress;

